#include <cstdint>
#include <cstring>
#include <iostream>
#include <chrono>

#include <grpcpp/grpcpp.h>

#include "jpeg_ipc.pb.h"
#include "jpeg_ipc.grpc.pb.h"

// Use the SAME generated bytes you already use for baseline
#include "../test_bytes.h"

#define RELEASE_ASSERT(cond, msg) \
  do { if(!(cond)) { std::cerr << "FAILED: " << #cond << ". " << msg << "\n"; std::exit(1);} } while(0)

int main(int argc, char** argv) {
  std::string addr = "unix:///tmp/jpeg_ipc.sock";
  if (argc == 3 && std::string(argv[1]) == "--addr") addr = argv[2];

  auto channel = grpc::CreateChannel(addr, grpc::InsecureChannelCredentials());
  auto stub = jpegipc::JpegRecode::NewStub(channel);

  const unsigned long input_size  = sizeof(inputData) - 1;
  const unsigned long output_size = sizeof(outputData) - 1;

  // Warmup RPCs
  for (int i = 0; i < 10; i++) {
    jpegipc::RecodeRequest req;
    req.set_quality(30);
    req.set_input((const char*)inputData, input_size);
    jpegipc::RecodeReply rep;
    grpc::ClientContext ctx;
    auto status = stub->Recode(&ctx, req, &rep);
    RELEASE_ASSERT(status.ok(), status.error_message().c_str());
  }

  const int test_iterations = 100;

  auto enter = std::chrono::high_resolution_clock::now();

  jpegipc::RecodeReply last_rep;
  for (int i = 0; i < test_iterations; i++) {
    jpegipc::RecodeRequest req;
    req.set_quality(30);
    req.set_input((const char*)inputData, input_size);

    grpc::ClientContext ctx;
    jpegipc::RecodeReply rep;
    auto status = stub->Recode(&ctx, req, &rep);
    RELEASE_ASSERT(status.ok(), status.error_message().c_str());

    last_rep = std::move(rep);
  }

  auto exit = std::chrono::high_resolution_clock::now();

  // Verify output matches the known-good bytes like baseline does
  RELEASE_ASSERT((unsigned long)last_rep.output().size() == output_size, "Size mismatch");
  const std::string& out = last_rep.output();
  for (unsigned long i = 0; i < output_size; i++) {
    if ((unsigned char)out[i] != outputData[i]) {
      std::cerr << "Output mismatch at index " << i << "\n";
      return 1;
    }
  }

  auto ns = std::chrono::duration_cast<std::chrono::nanoseconds>(exit - enter).count();
  std::cout << "JPEG recoding time (grpc ipc): " << (long long)(ns / test_iterations) << "\n";
  return 0;
}
